insert into public.site_content (page, section, content_key, value_en, value_fr) select $icb$global-fluency$icb$, $icb$hero$icb$, $icb$hero_body$icb$, $icb$The solution to our problems lay not in books or trainings but in our own minds. You are abrilliant person in your field already more difficult than English, why would English be difficult for you, to the point of even blocking your progress?$icb$, $icb$La solution à nos difficultés ne se trouve pas dans les livres ou les formations, mais dans notre propre esprit. Vous êtes déjà brillant dans un domaine plus difficile que l'anglais : pourquoi l'anglais vous bloquerait-il au point d'arrêter votre progression ?$icb$ where not exists (select 1 from public.site_content where page = $icb$global-fluency$icb$ and content_key = $icb$hero_body$icb$);
insert into public.site_content (page, section, content_key, value_en, value_fr) select $icb$global-fluency$icb$, $icb$description$icb$, $icb$why_body$icb$, $icb$The solution to our problems lay not in books or trainings but in our own minds. You are abrilliant person in your field already more difficult than English, why would English be difficult for you, to the point of even blocking your progress?$icb$, $icb$La solution à nos difficultés ne se trouve pas dans les livres ou les formations, mais dans notre propre esprit. Vous êtes déjà brillant dans un domaine plus difficile que l'anglais : pourquoi l'anglais vous bloquerait-il au point d'arrêter votre progression ?$icb$ where not exists (select 1 from public.site_content where page = $icb$global-fluency$icb$ and content_key = $icb$why_body$icb$);
insert into public.site_content (page, section, content_key, value_en, value_fr) select $icb$global-fluency$icb$, $icb$description$icb$, $icb$different_body$icb$, $icb$It's simple. In this program you get work with Roger, who is a software engineer, inventor and entrepreneur. He grew up in rural francophone Africa and rose to the world stage through self-reliance. He acquire English and Spanish through unconventional methods mostly for his own desire to have a seat on world stage. And today he share just that with hundreds of corporate leaders from around the world who simply can't afford to be viewed as a second class citizen in front of their international peers$icb$, $icb$C'est simple. Dans ce programme, vous travaillez avec Roger, ingénieur logiciel, inventeur et entrepreneur. Il a grandi dans une zone rurale d'Afrique francophone et a atteint la scène mondiale par lui-même. Il a appris l'anglais et l'espagnol par des méthodes peu conventionnelles, surtout pour prendre place sur cette scène. Aujourd'hui, il transmet cela à des centaines de dirigeants qui ne peuvent pas se permettre d'être perçus comme des interlocuteurs de second rang face à leurs pairs internationaux.$icb$ where not exists (select 1 from public.site_content where page = $icb$global-fluency$icb$ and content_key = $icb$different_body$icb$);
