insert into public.site_content (page, section, content_key, value_en, value_fr) select $icb$world-stage$icb$, $icb$program$icb$, $icb$description_1$icb$, $icb$World Stage is a private, 12-month communication mentorship for senior leaders who operate in complex, high-stakes environments. It helps you communicate with greater clarity, influence and composure — so you can lead more effectively and contribute to a more stable, cooperative world.$icb$, $icb$World Stage est un mentorat privé de 12 mois en communication pour les dirigeants qui évoluent dans des environnements complexes et à forts enjeux. Il vous aide à communiquer avec plus de clarté, d'influence et de calme, afin de diriger plus efficacement et de contribuer à un monde plus stable et plus coopératif.$icb$ where not exists (select 1 from public.site_content where page = $icb$world-stage$icb$ and content_key = $icb$description_1$icb$);
